    std::string trajet;
    std::cin >> trajet;
    std::size_t tiret = trajet.find("-");
    if (tiret == std::string::npos) {
        std::cout << "Format invalide\n";
    } else {
        std::cout << "Départ : " << trajet.substr(0, tiret) << "\n";
        std::cout << "Arrivée : " << trajet.substr(tiret + 1) << "\n";
    }
    return 0;
}

