#include <iostream>
#include <string>
#include <cctype>

bool numeroValide(std::string numero) {
    if (numero.size() != 8) {
        return false;
    }
    for (char c : numero) {
        if (!std::isdigit(c)) {
            return false;
        }
    }
    return true;
}

int main() {
    std::string numero;
    std::cin >> numero;
    if (numeroValide(numero)) {
        std::cout << "Numéro valide : +228";
        for (int i = 0; i < 8; i += 2) {
            std::cout << " " << numero.substr(i, 2);
        }
        std::cout << "\n";
    } else {
        std::cout << "Numéro invalide\n";
    }
    return 0;
}
